insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 371/2026, de 6 de mayo, por el que se crea y regula el Foro de Gobierno Abierto (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2026-9880', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b1-06-gobierno-abierto', 'I.6 El Gobierno Abierto y la Agenda 2030') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-06-gobierno-abierto' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Gobierno Abierto: concepto y evolución en España (preámbulo del RD 371/2026)"},{"n":"1.1","title":"La Alianza para el Gobierno Abierto y los Planes de Acción"},{"n":"1.2","title":"Principios informadores y pilares del Gobierno Abierto"},{"n":"2","title":"La transparencia como principio de la acción pública (Ley 19/2013)"},{"n":"3","title":"El Foro de Gobierno Abierto (RD 371/2026)"},{"n":"3.1","title":"Naturaleza, adscripción y fines (arts. 1-3)"},{"n":"3.2","title":"Composición: Presidencia, vicepresidencias, Pleno y Secretaría (arts. 4-6 y 13)"},{"n":"3.3","title":"Funcionamiento, Comisión Permanente y grupos de trabajo (arts. 12, 14-16)"},{"n":"3.4","title":"Grupo Interministerial, HazLab y Observatorio de Gobierno Abierto (arts. 17-19)"},{"n":"4","title":"La Agenda 2030 y los Objetivos de Desarrollo Sostenible"},{"n":"4.1","title":"Los 17 Objetivos de Desarrollo Sostenible"},{"n":"4.2","title":"Gobernanza en España: Grupo de Alto Nivel y Grupo de Trabajo Interministerial (Orden PCI/383/2019)"}]'::jsonb, '["Preámbulo RD 371/2026: «Desde que España se adhirió en 2011 a la Alianza para el Gobierno Abierto (OGP, por sus siglas en inglés), ha desarrollado una trayectoria sólida y progresiva en la promoción de políticas públicas basadas en la transparencia, la participación ciudadana, la rendición de cuentas, los datos abiertos y la integridad pública.»","Preámbulo RD 371/2026: «El Foro de Gobierno Abierto ejercerá sus funciones conforme a los principios de accesibilidad universal, transparencia, integridad, imparcialidad, cooperación, rendición de cuentas y lealtad institucional, que informarán todas sus actuaciones, deliberaciones y decisiones.»","Art. 19.4 RD 371/2026: «a) Transparencia. b) Participación ciudadana. c) Rendición de cuentas. d) Integridad pública. e) Colaboración y cocreación.»","Preámbulo Ley 19/2013: «La transparencia, el acceso a la información pública y las normas de buen gobierno deben ser los ejes fundamentales de toda acción política.»","Art. 1 Ley 19/2013: «Esta Ley tiene por objeto ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información relativa a aquella actividad y establecer las obligaciones de buen gobierno que deben cumplir los responsables públicos así como las consecuencias derivadas de su incumplimiento.»","Art. 2.1 RD 371/2026: «Se crea el Foro de Gobierno Abierto (en adelante, el Foro) como órgano colegiado de los previstos en el artículo 22.2 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, para la participación, con carácter paritario, de la sociedad civil en materia de gobierno abierto»","Art. 2.2 RD 371/2026: «El Foro está adscrito a la Secretaría de Estado de Función Pública.»","Art. 5.1 RD 371/2026: «Corresponde la Presidencia del Foro a la persona titular de la Secretaría de Estado de Función Pública»","Art. 6.1 RD 371/2026: «El Pleno del Foro estará integrado por la persona que ostente la Presidencia, la Secretaría y sesenta y cuatro vocales, treinta y dos en representación de las administraciones públicas y treinta y dos en representación de la sociedad civil»","Art. 12.1 RD 371/2026: «El Pleno del Foro se reunirá, con carácter ordinario, al menos dos veces al año, y con carácter extraordinario cuando así lo convoque su Presidencia, por iniciativa propia, o a solicitud de, al menos, un tercio de sus miembros.»","Art. 12.4 RD 371/2026: «Las decisiones del Foro se adoptarán preferentemente por consenso. En caso de no alcanzarse, se procederá a votación, requiriéndose mayoría simple de los miembros asistentes con derecho a voto.»","Art. 14.3 RD 371/2026: «La Comisión Permanente no tendrá funciones decisorias»","Art. 19.2 RD 371/2026: «El Observatorio contará con un entorno propio dentro del Portal de la Transparencia»","Lista de ODS ONU (ODS): «Objetivo 1: Poner fin a la pobreza»","Anexo Orden PCI/383/2019: «Un plan de acción integrado por 17 objetivos y 169 metas y aprobado por 193 países en la 70.º Asamblea de Naciones Unidas el 25 de septiembre de 2015.»","Anexo, apartado Tres Orden PCI/383/2019: «Se crea el Grupo de Trabajo Interministerial para la Agenda 2030, que tiene la finalidad de ser un foro técnico para procurar la colaboración y coordinación entre los Ministerios implicados, en la aplicación en España de la Agenda 2030 y el logro de los Objetivos de Desarrollo Sostenible.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2026-9880'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2026-9880', null, null, null, 'Otras normas citadas: Ley 19/2013 (https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887), ONU (ODS) (https://www.un.org/sustainabledevelopment/es/objetivos-de-desarrollo-sostenible/), Orden PCI/383/2019 (https://www.boe.es/buscar/act.php?id=BOE-A-2019-4905)'
  from public.topics t where t.slug = 'age-aux-b1-06-gobierno-abierto'
