insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b1-08-age', 'I.8 La Administración General del Estado') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-08-age' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Principios y estructura de la Administración General del Estado (arts. 54-56 LRJSP)"},{"n":"2","title":"Órganos centrales: los Ministerios y su estructura interna (arts. 57-60)"},{"n":"3","title":"Órganos superiores: Ministros y Secretarios de Estado (arts. 61-62)"},{"n":"4","title":"Órganos directivos (arts. 63-67)"},{"n":"4.1","title":"Subsecretarios y Secretarios generales (arts. 63-64)"},{"n":"4.2","title":"Secretarios generales técnicos, Directores generales y Subdirectores generales (arts. 65-67)"},{"n":"5","title":"Servicios comunes de los Ministerios (art. 68)"},{"n":"6","title":"Órganos territoriales (arts. 69-77)"},{"n":"6.1","title":"Delegados del Gobierno en las Comunidades Autónomas (arts. 72-73)"},{"n":"6.2","title":"Subdelegados del Gobierno y Directores Insulares (arts. 70, 74-75)"},{"n":"7","title":"Otros órganos: órganos colegiados de la Administración periférica (arts. 78-79)"},{"n":"8","title":"La Administración General del Estado en el exterior (arts. 55.5 y 80)"}]'::jsonb, '["Art. 54.1 Ley 40/2015: «La Administración General del Estado actúa y se organiza de acuerdo con los principios establecidos en el artículo 3, así como los de descentralización funcional y desconcentración funcional y territorial.»","Art. 55.2 Ley 40/2015: «La Administración General del Estado comprende: a) La Organización Central, que integra los Ministerios y los servicios comunes. b) La Organización Territorial. c) La Administración General del Estado en el exterior.»","Art. 55.3 Ley 40/2015: «En la organización central son órganos superiores y órganos directivos: a) Órganos superiores: 1.º Los Ministros. 2.º Los Secretarios de Estado. b) Órganos directivos: 1.º Los Subsecretarios y Secretarios generales. 2.º Los Secretarios generales técnicos y Directores generales. 3.º Los Subdirectores generales.»","Art. 55.9 Ley 40/2015: «Corresponde a los órganos superiores establecer los planes de actuación de la organización situada bajo su responsabilidad y a los órganos directivos su desarrollo y ejecución.»","Art. 57.3 Ley 40/2015: «La determinación del número, la denominación y el ámbito de competencia respectivo de los Ministerios y las Secretarías de Estado se establecen mediante Real Decreto del Presidente del Gobierno.»","Art. 58.2 Ley 40/2015: «Los Ministerios contarán, en todo caso, con una Subsecretaría, y dependiendo de ella una Secretaría General Técnica, para la gestión de los servicios comunes previstos en este Título.»","Art. 60.1 Ley 40/2015: «Los Ministros son los jefes superiores del Departamento y superiores jerárquicos directos de los Secretarios de Estado y Subsecretarios.»","Art. 62.1 Ley 40/2015: «Los Secretarios de Estado son directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica.»","Art. 63.1 Ley 40/2015: «Los Subsecretarios ostentan la representación ordinaria del Ministerio, dirigen los servicios comunes, ejercen las competencias correspondientes a dichos servicios comunes»","Art. 66.1 Ley 40/2015: «Los Directores generales son los titulares de los órganos directivos encargados de la gestión de una o varias áreas funcionalmente homogéneas del Ministerio.»","Art. 55.4 Ley 40/2015: «En la organización territorial de la Administración General del Estado son órganos directivos tanto los Delegados del Gobierno en las Comunidades Autónomas, que tendrán rango de Subsecretario, como los Subdelegados del Gobierno en las provincias, los cuales tendrán nivel de Subdirector general.»","Art. 72.1 Ley 40/2015: «Los Delegados del Gobierno representan al Gobierno de la Nación en el territorio de la respectiva Comunidad Autónoma, sin perjuicio de la representación ordinaria del Estado en las mismas a través de sus respectivos Presidentes.»","Art. 72.3 Ley 40/2015: «Los Delegados del Gobierno son órganos directivos con rango de Subsecretario que dependen orgánicamente del Presidente del Gobierno y funcionalmente del Ministerio competente por razón de la materia.»","Art. 74 Ley 40/2015: «En cada provincia y bajo la inmediata dependencia del Delegado del Gobierno en la respectiva Comunidad Autónoma, existirá un Subdelegado del Gobierno, con nivel de Subdirector General, que será nombrado por aquél mediante el procedimiento de libre designación entre funcionarios de carrera del Estado, de las Comunidades Autónomas o de las Entidades Locales, pertenecientes a Cuerpos o Escalas clasificados como Subgrupo A1.»","Art. 78.1 Ley 40/2015: «La Comisión interministerial de coordinación de la Administración periférica del Estado es un órgano colegiado, adscrito al Ministerio de Hacienda y Administraciones Públicas.»","Art. 55.5 Ley 40/2015: «En la Administración General del Estado en el exterior son órganos directivos los embajadores y representantes permanentes ante Organizaciones internacionales.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', null, null, null, null
