insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Principios generales de la organización territorial (arts. 137-139 CE)"},{"n":"2","title":"Las Comunidades Autónomas: acceso a la autonomía y Estatutos (arts. 143-147 y 151-152 CE)"},{"n":"3","title":"Distribución de competencias entre el Estado y las Comunidades Autónomas (arts. 148-150 CE)"},{"n":"3.1","title":"Competencias de las Comunidades Autónomas (art. 148 CE)"},{"n":"3.2","title":"Competencias exclusivas del Estado y cláusulas de cierre (art. 149 CE)"},{"n":"3.3","title":"Leyes marco, de transferencia o delegación y de armonización (art. 150 CE)"},{"n":"4","title":"Control de las Comunidades Autónomas y coerción estatal (arts. 153-155 CE)"},{"n":"5","title":"La Administración local en la Constitución (arts. 140-142 CE)"},{"n":"6","title":"Entidades que integran la Administración local (arts. 1 y 3 LBRL)"},{"n":"7","title":"El municipio: elementos, organización y competencias (arts. 11-28 LBRL)"},{"n":"8","title":"La provincia (arts. 31-38 LBRL)"},{"n":"9","title":"La isla (arts. 41 LBRL y 141.4 CE)"}]'::jsonb, '["Art. 137 CE: «El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan. Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.»","Art. 143.1 CE: «En el ejercicio del derecho a la autonomía reconocido en el artículo 2 de la Constitución, las provincias limítrofes con características históricas, culturales y económicas comunes, los territorios insulares y las provincias con entidad regional histórica podrán acceder a su autogobierno y constituirse en Comunidades Autónomas con arreglo a lo previsto en este Título y en los respectivos Estatutos.»","Art. 147.1 CE: «Dentro de los términos de la presente Constitución, los Estatutos serán la norma institucional básica de cada Comunidad Autónoma y el Estado los reconocerá y amparará como parte integrante de su ordenamiento jurídico.»","Art. 148.2 CE: «Transcurridos cinco años, y mediante la reforma de sus Estatutos, las Comunidades Autónomas podrán ampliar sucesivamente sus competencias dentro del marco establecido en el artículo 149.»","Art. 149.3 CE: «Las materias no atribuidas expresamente al Estado por esta Constitución podrán corresponder a las Comunidades Autónomas, en virtud de sus respectivos Estatutos. La competencia sobre las materias que no se hayan asumido por los Estatutos de Autonomía corresponderá al Estado, cuyas normas prevalecerán, en caso de conflicto, sobre las de las Comunidades Autónomas en todo lo que no esté atribuido a la exclusiva competencia de éstas. El derecho estatal será, en todo caso, supletorio del derecho de las Comunidades Autónomas.»","Art. 150.2 CE: «El Estado podrá transferir o delegar en las Comunidades Autónomas, mediante ley orgánica, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.»","Art. 155.1 CE: «Si una Comunidad Autónoma no cumpliere las obligaciones que la Constitución u otras leyes le impongan, o actuare de forma que atente gravemente al interés general de España, el Gobierno, previo requerimiento al Presidente de la Comunidad Autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado, podrá adoptar las medidas necesarias para obligar a aquélla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general.»","Art. 140 CE: «La Constitución garantiza la autonomía de los municipios. Estos gozarán de personalidad jurídica plena. Su gobierno y administración corresponde a sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales.»","Art. 141.1 CE: «La provincia es una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado. Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica.»","Art. 3 Ley 7/1985: «Son Entidades Locales territoriales: a) El Municipio. b) La Provincia. c) La Isla en los archipiélagos balear y canario. 2. Gozan, asimismo, de la condición de Entidades Locales: a) Las Comarcas u otras entidades que agrupen varios Municipios, instituidas por las Comunidades Autónomas de conformidad con esta Ley y los correspondientes Estatutos de Autonomía. b) Las Áreas Metropolitanas. c) Las Mancomunidades de Municipios.»","Art. 11 Ley 7/1985: «El Municipio es la entidad local básica de la organización territorial del Estado. Tiene personalidad jurídica y plena capacidad para el cumplimiento de sus fines. 2. Son elementos del Municipio el territorio, la población y la organización.»","Art. 15 Ley 7/1985: «El conjunto de personas inscritas en el Padrón municipal constituye la población del municipio. Los inscritos en el Padrón municipal son los vecinos del municipio.»","Art. 20.1.a) Ley 7/1985: «El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos.»","Art. 31.1 Ley 7/1985: «La Provincia es una entidad local determinada por la agrupación de Municipios, con personalidad jurídica propia y plena capacidad para el cumplimiento de sus fines.»","Art. 32.1 Ley 7/1985: «El Presidente, los Vicepresidentes, la Junta de Gobierno y el Pleno existen en todas las Diputaciones.»","Art. 141.4 CE: «En los archipiélagos, las islas tendrán además su administración propia en forma de Cabildos o Consejos.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: Ley 7/1985 (https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392)'
