insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El marco institucional de la Unión Europea (art. 13 TUE)"},{"n":"2","title":"El Parlamento Europeo (art. 14 TUE; arts. 223-234 TFUE)"},{"n":"2.1","title":"Funciones, composición y elección"},{"n":"2.2","title":"Control: comisiones de investigación, Defensor del Pueblo Europeo y moción de censura"},{"n":"3","title":"El Consejo Europeo y su Presidente (art. 15 TUE; arts. 235-236 TFUE)"},{"n":"4","title":"El Consejo (art. 16 TUE; arts. 237-243 TFUE)"},{"n":"4.1","title":"Formaciones, presidencia, mayoría cualificada y COREPER"},{"n":"5","title":"La Comisión Europea y el Alto Representante (arts. 17-18 TUE; arts. 244-250 TFUE)"},{"n":"5.1","title":"Nombramiento, responsabilidad colegiada y cese"},{"n":"6","title":"El Tribunal de Justicia de la Unión Europea (art. 19 TUE; arts. 251-257 TFUE)"},{"n":"6.1","title":"Estructura y composición"},{"n":"6.2","title":"Competencias"}]'::jsonb, '["Art. 13.2 TUE: «Cada institución actuará dentro de los límites de las atribuciones que le confieren los Tratados, con arreglo a los procedimientos, condiciones y fines establecidos en los mismos. Las instituciones mantendrán entre sí una cooperación leal.»","Art. 14.1 TUE: «El Parlamento Europeo ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria. Ejercerá funciones de control político y consultivas, en las condiciones establecidas en los Tratados. Elegirá al Presidente de la Comisión.»","Art. 14.2 TUE: «Su número no excederá de setecientos cincuenta, más el Presidente. La representación de los ciudadanos será decrecientemente proporcional, con un mínimo de seis diputados por Estado miembro. No se asignará a ningún Estado miembro más de noventa y seis escaños.»","Art. 228.2 TFUE: «El Defensor del Pueblo será elegido después de cada elección del Parlamento Europeo para toda la legislatura. Su mandato será renovable.»","Art. 234 TFUE: «Si la moción de censura es aprobada por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo, los miembros de la Comisión deberán dimitir colectivamente de sus cargos»","Art. 15.1 TUE: «El Consejo Europeo dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales. No ejercerá función legislativa alguna.»","Art. 15.2 TUE: «El Consejo Europeo estará compuesto por los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión.»","Art. 15.5 TUE: «El Consejo Europeo elegirá a su Presidente por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez.»","Art. 16.2 TUE: «El Consejo estará compuesto por un representante de cada Estado miembro, de rango ministerial, facultado para comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho de voto.»","Art. 16.4 TUE: «A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55 % de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión.»","Art. 17.1 TUE: «La Comisión promoverá el interés general de la Unión y tomará las iniciativas adecuadas con este fin.»","Art. 17.3 TUE: «El mandato de la Comisión será de cinco años.»","Art. 17.8 TUE: «La Comisión tendrá una responsabilidad colegiada ante el Parlamento Europeo.»","Art. 18.3 TUE: «El Alto Representante presidirá el Consejo de Asuntos Exteriores.»","Art. 19.1 TUE: «El Tribunal de Justicia de la Unión Europea comprenderá el Tribunal de Justicia, el Tribunal General y los tribunales especializados. Garantizará el respeto del Derecho en la interpretación y aplicación de los Tratados.»","Art. 19.2 TUE: «Serán nombrados de común acuerdo por los Gobiernos de los Estados miembros para un período de seis años. Los jueces y abogados generales salientes podrán ser nombrados de nuevo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT', null, null, null, 'Otras normas citadas: TFUE (https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016E/TXT)'
