insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El presupuesto en la Constitución (art. 134 CE)"},{"n":"2","title":"Principios de programación y gestión presupuestaria (arts. 26-27 LGP)"},{"n":"3","title":"Contenido de los Presupuestos Generales del Estado (arts. 32-35 LGP)"},{"n":"4","title":"Elaboración y remisión a las Cortes Generales (arts. 36-37 LGP)"},{"n":"5","title":"Prórroga presupuestaria (art. 134.4 CE; art. 38 LGP)"},{"n":"6","title":"Estructura de los estados de gastos e ingresos (arts. 39-41 LGP)"},{"n":"7","title":"Los créditos: especialidad, limitación y temporalidad (arts. 42-50 LGP)"},{"n":"8","title":"Fases del ciclo presupuestario: la ejecución del gasto (arts. 73-74 LGP)"}]'::jsonb, '["Art. 134.1 CE: «Corresponde al Gobierno la elaboración de los Presupuestos Generales del Estado y a las Cortes Generales, su examen, enmienda y aprobación.»","Art. 134.2 CE: «Los Presupuestos Generales del Estado tendrán carácter anual, incluirán la totalidad de los gastos e ingresos del sector público estatal y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado.»","Art. 134.3 CE: «El Gobierno deberá presentar ante el Congreso de los Diputados los Presupuestos Generales del Estado al menos tres meses antes de la expiración de los del año anterior.»","Art. 134.7 CE: «La Ley de Presupuestos no puede crear tributos. Podrá modificarlos cuando una ley tributaria sustantiva así lo prevea.»","Art. 26.1 Ley 47/2003: «La programación presupuestaria se regirá por los principios de estabilidad presupuestaria, sostenibilidad financiera, plurianualidad, transparencia, eficiencia en la asignación y utilización de los recursos públicos, responsabilidad y lealtad institucional»","Art. 32 Ley 47/2003: «Los Presupuestos Generales del Estado constituyen la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por cada uno de los órganos y entidades que forman parte del sector público estatal.»","Art. 34.1 Ley 47/2003: «El ejercicio presupuestario coincidirá con el año natural»","Art. 36.5 Ley 47/2003: «Corresponderá al Ministro de Hacienda elevar al acuerdo del Gobierno el anteproyecto de la Ley de Presupuestos Generales del Estado.»","Art. 37.1 Ley 47/2003: «El proyecto de Ley de Presupuestos Generales del Estado, integrado por el articulado con sus anexos y los estados de ingresos y de gastos, con el nivel de especificación de créditos establecido en los artículos 40 y 41 de esta ley, será remitido a las Cortes Generales antes del día 1 de octubre del año anterior al que se refiera.»","Art. 38.1 Ley 47/2003: «Si la Ley de Presupuestos Generales del Estado no se aprobara antes del primer día del ejercicio económico correspondiente, se considerarán automáticamente prorrogados los presupuestos iniciales del ejercicio anterior hasta la aprobación y publicación de los nuevos»","Art. 40.1 Ley 47/2003: «Los estados de gastos de los presupuestos a que se refiere el artículo 33.1.ª) de esta ley se estructurarán de acuerdo con las siguientes clasificaciones: a) La clasificación orgánica […] b) La clasificación por programas […] c) La clasificación económica, que agrupará los créditos por capítulos separando las operaciones corrientes, las de capital, las financieras y el Fondo de Contingencia de ejecución presupuestaria.»","Art. 42 Ley 47/2003: «Los créditos para gastos se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados por la Ley de Presupuestos o a la que resulte de las modificaciones aprobadas conforme a esta ley.»","Art. 46 Ley 47/2003: «Los créditos para gastos son limitativos. No podrán adquirirse compromisos de gasto ni adquirirse obligaciones por cuantía superior al importe de los créditos autorizados en los estados de gastos»","Art. 49.2 Ley 47/2003: «Los créditos para gastos que en el último día del ejercicio presupuestario no estén afectados al cumplimiento de obligaciones ya reconocidas, quedarán anulados de pleno derecho, sin perjuicio de lo establecido en el artículo 58 de esta ley.»","Art. 73.1 Ley 47/2003: «a) Aprobación del gasto. b) Compromiso de gasto. c) Reconocimiento de la obligación. d) Ordenación del pago. e) Pago material.»","Art. 73.4 Ley 47/2003: «El reconocimiento de la obligación es el acto mediante el que se declara la existencia de un crédito exigible contra la Hacienda Pública estatal o contra la Seguridad Social, derivado de un gasto aprobado y comprometido y que comporta la propuesta de pago correspondiente.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229)'
  from public.topics t where t.slug = 'age-aux-b1-15-presupuesto'
