insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 366/2007, de 16 de marzo, accesibilidad y no discriminación de las personas con discapacidad en sus relaciones con la AGE (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6239', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b2-01-atencion-publico', 'II.1 Atención al público y atención de personas con discapacidad') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b2-01-atencion-publico' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La información administrativa como cauce de acogida e información (RD 208/1996, art. 1)"},{"n":"2","title":"Funciones de atención al ciudadano (RD 208/1996, art. 4)"},{"n":"2.1","title":"Recepción y acogida"},{"n":"2.2","title":"Orientación e información: límites"},{"n":"2.3","title":"Gestión, iniciativas, quejas y derecho de petición"},{"n":"3","title":"Derechos de las personas en sus relaciones con las Administraciones (Ley 39/2015, art. 13)"},{"n":"4","title":"Personas con discapacidad: concepto (RDL 1/2013, art. 4)"},{"n":"5","title":"Accesibilidad en las relaciones con la AGE (RD 366/2007)"},{"n":"5.1","title":"Objeto, medios preferentes y principios (arts. 1-2)"},{"n":"5.2","title":"Oficinas de Atención al Ciudadano: ubicación, acceso, señalización y puestos (arts. 4-9)"},{"n":"5.3","title":"Excepciones (art. 11)"},{"n":"5.4","title":"Impresos, documentos y formación del personal (arts. 12 y 14)"}]'::jsonb, '["Art. 1 RD 208/1996: «La información administrativa es un cauce adecuado a través del cual los ciudadanos pueden acceder al conocimiento de su derechos y obligaciones y a la utilización de los bienes y servicios públicos.»","Art. 4.a) RD 208/1996: «a) De recepción y acogida a los ciudadanos, al objeto de facilitarles la orientación y ayuda que precisen en el momento inicial de su visita, y, en particular, la relativa a la localización de dependencias y funcionarios.»","Art. 4.b) RD 208/1996: «Esta forma de facilitar a los ciudadanos el ejercicio de sus derechos, en ningún caso podrá entrañar una interpretación normativa, a la que se refiere el artículo 37.10 de la Ley de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común, ni consideración jurídica o económica, sino una simple determinación de conceptos, información de opciones legales o colaboración en la cumplimentación de impresos o solicitudes.»","Art. 4.f) RD 208/1996: «f) De asistencia a los ciudadanos en el ejercicio del derecho de petición, reconocido por los artículos 29 y 77 de la Constitución.»","Art. 13.e) Ley 39/2015: «e) A ser tratados con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos y el cumplimiento de sus obligaciones.»","Art. 4.1 RDL 1/2013: «1. Son personas con discapacidad aquellas que presentan deficiencias físicas, mentales, intelectuales o sensoriales, previsiblemente permanentes que, al interactuar con diversas barreras, puedan impedir su participación plena y efectiva en la sociedad, en igualdad de condiciones con los demás.»","Art. 1.1 RD 366/2007: «1. El presente real decreto regula las condiciones de accesibilidad y no discriminación que, respecto de las personas con discapacidad, deben presentar las Oficinas de Atención al Ciudadano, impresos y cualquier otro medio que la Administración General del Estado dedica específicamente y en el ámbito de sus competencias a las relaciones con los ciudadanos.»","Art. 2.a) RD 366/2007: «a) La garantía de la igualdad de oportunidades, la no discriminación por razón de discapacidad y la accesibilidad universal.»","Art. 4.1 RD 366/2007: «1. La Administración General del Estado ubicará las Oficinas de Atención al Ciudadano en entornos que garanticen el acceso de las personas con discapacidad.»","Art. 7.c) RD 366/2007: «c) La información relevante se dispondrá, al menos, en dos de las tres modalidades sensoriales: visual, acústica y táctil (altorrelieve o braille), para que pueda ser percibida también plenamente por las personas con discapacidad visual y auditiva.»","Art. 8.2.d) RD 366/2007: «d) Los mostradores y puntos de atención deberán contar con sistemas de bucle de inducción magnética, debidamente señalizados, para permitir a las personas usuarias de prótesis auditivas la mejor audición y comprensión posibles.»","Art. 11.1 RD 366/2007: «1. Las condiciones de accesibilidad y no discriminación establecidas en el presente capítulo podrán ser parcialmente exceptuadas cuando en el edificio en el que se ubique la Oficina, o en su entorno, concurran circunstancias de infraestructura o protección del patrimonio que hagan su aplicación imposible material o económicamente.»","Art. 12.2 RD 366/2007: «2. A requerimiento de la persona con discapacidad, se ofrecerán en formatos alternativos utilizando tipografías grandes o ampliadas, en braille, o bien se contará con personal de apoyo para facilitar su cumplimentación.»","Art. 14.2 RD 366/2007: «2. En la formación del personal de la Administración General del Estado encargado de la prestación de servicios de atención al ciudadano se atenderá especialmente al conocimiento de las distintas discapacidades y sus consecuencias en el desarrollo de los servicios de atención, en el trato e interacción con las personas con discapacidad y en el uso de medios auxiliares facilitadores de dicho trato.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6239'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6239', null, null, null, 'Otras normas citadas: RD 208/1996 (https://www.boe.es/buscar/act.php?id=BOE-A-1996-4997), Ley 39/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565), RDL 1/2013 (https://www.boe.es/buscar/act.php?id=BOE-A-2013-12632)'
  from public.topics t where t.slug = 'age-aux-b2-01-atencion-publico'
