insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2001, de 12 de noviembre, reguladora del Derecho de Petición (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-21090', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b2-02-informacion-administrativa', 'II.2 Los servicios de información administrativa: iniciativas, reclamaciones, quejas y peticiones') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b2-02-informacion-administrativa' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La información administrativa: general y particular (RD 208/1996, arts. 1-3)"},{"n":"1.1","title":"Información general (art. 2)"},{"n":"1.2","title":"Información particular (art. 3)"},{"n":"2","title":"Iniciativas, quejas y reclamaciones como funciones de atención (art. 4)"},{"n":"3","title":"Organización de los servicios de información administrativa (arts. 5-10)"},{"n":"3.1","title":"Unidades departamentales y Centro de Información Administrativa (arts. 5-6)"},{"n":"3.2","title":"Oficinas de información y atención al ciudadano (arts. 7-10)"},{"n":"4","title":"Quejas y sugerencias en el marco de calidad (RD 951/2005, arts. 3 y 14-19)"},{"n":"4.1","title":"Presentación y tramitación (arts. 14-15)"},{"n":"4.2","title":"Contestación, seguimiento y efectos (arts. 16-19)"},{"n":"5","title":"El derecho de petición (LO 4/2001)"},{"n":"5.1","title":"Titulares, destinatarios, objeto y forma (arts. 1-6)"},{"n":"5.2","title":"Tramitación, inadmisión y contestación (arts. 7-11)"},{"n":"5.3","title":"Protección jurisdiccional (art. 12)"}]'::jsonb, '["Art. 2.2 RD 208/1996: «2. La información general se facilitará obligatoriamente a los ciudadanos, sin exigir para ello la acreditación de legitimación alguna.»","Art. 3.1 RD 208/1996: «Esta información sólo podrá ser facilitada a las personas que tengan la condición de interesados en cada procedimiento o a sus representantes legales»","Art. 4.e) RD 208/1996: «e) De recepción de las quejas y reclamaciones de los ciudadanos por las tardanzas, desatenciones o por cualquier otro tipo de actuación irregular que observen en el funcionamiento de las dependencias administrativas.»","Art. 5.1 RD 208/1996: «1. En cada Ministerio el titular de la Subdirección General que tenga encomendada la competencia sobre la información administrativa ostentará la jefatura de la unidad departamental de información administrativa.»","Art. 14 RD 951/2005: «Los órganos y organismos incluidos en el ámbito de aplicación de este real decreto determinarán la unidad responsable de la gestión de las quejas y sugerencias con objeto de recoger y tramitar tanto las manifestaciones de insatisfacción de los usuarios con los servicios como las iniciativas para mejorar su calidad.»","Art. 15.2 RD 951/2005: «2. Los usuarios podrán formular sus quejas o sugerencias presencialmente, por correo postal y por medios telemáticos. Las quejas y sugerencias presentadas por correo electrónico o a través de Internet deberán estar suscritas con la firma electrónica del interesado.»","Art. 16.1 RD 951/2005: «1. Recibida la queja o sugerencia, la unidad a la que se refiere el artículo 14 informará al interesado de las actuaciones realizadas en el plazo de 20 días hábiles.»","Art. 19 RD 951/2005: «Las quejas formuladas conforme a lo previsto en este real decreto no tendrán, en ningún caso, la calificación de recurso administrativo ni su presentación interrumpirá los plazos establecidos en la normativa vigente.»","Art. 1.1 LO 4/2001: «1. Toda persona natural o jurídica, prescindiendo de su nacionalidad, puede ejercer el derecho de petición, individual o colectivamente, en los términos y con los efectos establecidos por la presente Ley y sin que de su ejercicio pueda derivarse perjuicio alguno para el peticionario.»","Art. 3 LO 4/2001: «No son objeto de este derecho aquellas solicitudes, quejas o sugerencias para cuya satisfacción el ordenamiento jurídico establezca un procedimiento específico distinto al regulado en la presente Ley.»","Art. 6.2 LO 4/2001: «2. La administración, institución pública o autoridad que reciba una petición acusará recibo de la misma y lo comunicará al interesado dentro de los diez días siguientes a su recepción.»","Art. 9.1 LO 4/2001: «1. La declaración de inadmisibilidad será siempre motivada y deberá acordarse y notificarse al peticionario en los cuarenta y cinco días hábiles siguientes al de presentación del escrito de petición.»","Art. 11.1 LO 4/2001: «1. Una vez admitida a trámite una petición, la autoridad u órgano competente vendrán obligados a contestar y a notificar la contestación en el plazo máximo de tres meses a contar desde la fecha de su presentación.»","Art. 12 LO 4/2001: «El derecho de petición es susceptible de tutela judicial mediante las vías establecidas en el artículo 53.2 de la Constitución, sin perjuicio de cualesquiera otras acciones que el peticionario estime procedentes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-21090'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-21090', null, null, null, 'Otras normas citadas: RD 208/1996 (https://www.boe.es/buscar/act.php?id=BOE-A-1996-4997), RD 951/2005 (https://www.boe.es/buscar/act.php?id=BOE-A-2005-14836)'
  from public.topics t where t.slug = 'age-aux-b2-02-informacion-administrativa'
