insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto de documento (Ley 39/2015, arts. 26-28; RD 1708/2011, art. 2)"},{"n":"1.1","title":"Documentos públicos administrativos y documento electrónico (art. 26 LPAC)"},{"n":"1.2","title":"Copias auténticas y documentos aportados (arts. 27-28 LPAC)"},{"n":"2","title":"El registro: funciones (Ley 39/2015, art. 16; RD 203/2021, arts. 37-40)"},{"n":"2.1","title":"Registro Electrónico General y asientos"},{"n":"2.2","title":"Lugares de presentación y oficinas de asistencia en materia de registros"},{"n":"3","title":"El archivo: concepto y funciones (Ley 39/2015, art. 17; RD 1708/2011, arts. 2 y 14)"},{"n":"4","title":"Clases de archivo según el ciclo vital (RD 1708/2011, arts. 8-12)"},{"n":"4.1","title":"Archivos de oficina o de gestión y archivos centrales"},{"n":"4.2","title":"Archivo intermedio y archivos históricos"},{"n":"5","title":"Calendarios de conservación, valoración y eliminación (RD 1708/2011, arts. 2 y 15)"},{"n":"6","title":"Conservación y archivo electrónico único (RD 203/2021, arts. 53-55)"}]'::jsonb, '["Art. 26.1 Ley 39/2015: «1. Se entiende por documentos públicos administrativos los válidamente emitidos por los órganos de las Administraciones Públicas. Las Administraciones Públicas emitirán los documentos administrativos por escrito, a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia.»","Art. 2.2.b) RD 1708/2011: «b) Documento de archivo: Ejemplar en cualquier tipo de soporte, testimonio de las actividades y funciones de las personas físicas y jurídicas, públicas o privadas.»","Art. 27.2 Ley 39/2015: «Las copias auténticas tendrán la misma validez y eficacia que los documentos originales.»","Art. 16.1 Ley 39/2015: «1. Cada Administración dispondrá de un Registro Electrónico General, en el que se hará el correspondiente asiento de todo documento que sea presentado o que se reciba en cualquier órgano administrativo, Organismo público o Entidad vinculado o dependiente a éstos. También se podrán anotar en el mismo, la salida de los documentos oficiales dirigidos a otros órganos o particulares.»","Art. 16.2 Ley 39/2015: «2. Los asientos se anotarán respetando el orden temporal de recepción o salida de los documentos, e indicarán la fecha del día en que se produzcan. Concluido el trámite de registro, los documentos serán cursados sin dilación a sus destinatarios y a las unidades administrativas correspondientes desde el registro en que hubieran sido recibidas.»","Art. 16.4 Ley 39/2015: «4. Los documentos que los interesados dirijan a los órganos de las Administraciones Públicas podrán presentarse: a) En el registro electrónico de la Administración u Organismo al que se dirijan, así como en los restantes registros electrónicos de cualquiera de los sujetos a los que se refiere el artículo 2.1. b) En las oficinas de Correos, en la forma que reglamentariamente se establezca. c) En las representaciones diplomáticas u oficinas consulares de España en el extranjero. d) En las oficinas de asistencia en materia de registros. e) En cualquier otro que establezcan las disposiciones vigentes.»","Art. 17.1 Ley 39/2015: «1. Cada Administración deberá mantener un archivo electrónico único de los documentos electrónicos que correspondan a procedimientos finalizados, en los términos establecidos en la normativa reguladora aplicable.»","Art. 2.2.e) RD 1708/2011: «e) Ciclo vital de documentos: Son las diferentes etapas por las que atraviesan los documentos desde que se producen hasta su eliminación conforme al procedimiento establecido, o en su caso, su conservación permanente.»","Art. 8 RD 1708/2011: «Los Archivos del Sistema de Archivos de la Administración General del Estado, atendiendo al ciclo vital de los documentos, se clasifican en: a) Archivos de oficina o de gestión. b) Archivos generales o centrales de los Ministerios y de los organismos públicos dependientes de los mismos. c) Archivo intermedio. d) Archivos históricos.»","Art. 9 RD 1708/2011: «Son aquellos archivos existentes en todos los órganos y unidades administrativas para la custodia de los documentos en fase de tramitación o sometidos a continua utilización y consulta administrativa.»","Art. 10.1 RD 1708/2011: «1. Son aquellos archivos existentes en los Ministerios y organismos públicos para la custodia de los documentos, una vez finalizada su tramitación y transcurridos los plazos establecidos por la normativa vigente o en los calendarios de conservación.»","Art. 11 RD 1708/2011: «El Archivo General de la Administración, es el archivo intermedio de la Administración General del Estado, según la normativa vigente.»","Art. 12.2 RD 1708/2011: «2. El Archivo Histórico Nacional ejerce las funciones de archivo histórico de la Administración General del Estado.»","Art. 2.2.f) RD 1708/2011: «f) Calendario de conservación: Es el instrumento de trabajo fruto del proceso de valoración documental, en el que se recoge el plazo de permanencia de los documentos de archivo en cada una de las fases del ciclo vital para su selección, eliminación o conservación permanente y, en su caso, el método y procedimiento de selección, eliminación o conservación en otro soporte.»","Art. 55.1 RD 203/2021: «1. El archivo electrónico único de cada Administración es el conjunto de sistemas y servicios que sustenta la gestión, custodia y recuperación de los documentos y expedientes electrónicos así como de otras agrupaciones documentales o de información una vez finalizados los procedimientos administrativos o actuaciones correspondientes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-18541'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-18541', null, null, null, 'Otras normas citadas: Ley 39/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565), RD 203/2021 (https://www.boe.es/buscar/act.php?id=BOE-A-2021-5032)'
  from public.topics t where t.slug = 'age-aux-b2-03-documento-registro-archivo'
