insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Administración electrónica: principios y derecho a relacionarse electrónicamente (RD 203/2021, arts. 2-4; Ley 39/2015, arts. 12-14)"},{"n":"2","title":"Identificación y firma electrónica (Ley 39/2015, arts. 9-11; RD 203/2021, art. 26)"},{"n":"3","title":"Portales de internet y sedes electrónicas (Ley 40/2015, arts. 38-39; RD 203/2021, arts. 5-12)"},{"n":"4","title":"El Punto de Acceso General de la AGE y la Carpeta Ciudadana (RD 203/2021, arts. 7-8)"},{"n":"5","title":"Notificaciones electrónicas (Ley 39/2015, arts. 41-43)"},{"n":"6","title":"Actuación administrativa automatizada y archivo electrónico (Ley 40/2015, arts. 41-46)"},{"n":"7","title":"Accesibilidad de los sitios web del sector público (RD 1112/2018)"},{"n":"8","title":"Oficinas integradas de atención al ciudadano (RD 208/1996, art. 10)"}]'::jsonb, '["Art. 2.b) RD 203/2021: «b) El principio de accesibilidad, entendido como el conjunto de principios y técnicas que se deben respetar al diseñar, construir, mantener y actualizar los servicios electrónicos para garantizar la igualdad y la no discriminación en el acceso de las personas usuarias, en particular de las personas con discapacidad y de las personas mayores.»","Art. 14.1 Ley 39/2015: «1. Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas. El medio elegido por la persona para comunicarse con las Administraciones Públicas podrá ser modificado por aquella en cualquier momento.»","Art. 11.1 Ley 39/2015: «1. Con carácter general, para realizar cualquier actuación prevista en el procedimiento administrativo, será suficiente con que los interesados acrediten previamente su identidad a través de cualquiera de los medios de identificación previstos en esta Ley.»","Art. 38.1 Ley 40/2015: «1. La sede electrónica es aquella dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública, o bien a una o varios organismos públicos o entidades de Derecho Público en el ejercicio de sus competencias.»","Art. 39 Ley 40/2015: «Se entiende por portal de internet el punto de acceso electrónico cuya titularidad corresponda a una Administración Pública, organismo público o entidad de Derecho Público que permite el acceso a través de internet a la información publicada y, en su caso, a la sede electrónica correspondiente.»","Art. 7.2 RD 203/2021: «2. El PAGe de cada Administración Pública facilitará el acceso a los servicios, trámites e información de los órganos, organismos públicos y entidades vinculados o dependientes de la Administración Pública correspondiente.»","Art. 7.3 RD 203/2021: «3. El PAGe dispondrá de una sede electrónica, a través de la cual se podrá acceder a todas las sedes electrónicas y sedes asociadas de la Administración Pública correspondiente.»","Art. 8.1 RD 203/2021: «1. La Carpeta Ciudadana es el área personalizada de las personas interesadas a que se refiere el artículo 7.3 en su relación con el sector público estatal.»","Art. 41.1 Ley 39/2015: «1. Las notificaciones se practicarán preferentemente por medios electrónicos y, en todo caso, cuando el interesado resulte obligado a recibirlas por esta vía.»","Art. 43.2 Ley 39/2015: «2. Las notificaciones por medios electrónicos se entenderán practicadas en el momento en que se produzca el acceso a su contenido.»","Art. 43.4 Ley 39/2015: «4. Los interesados podrán acceder a las notificaciones desde el Punto de Acceso General electrónico de la Administración, que funcionará como un portal de acceso.»","Art. 41.1 Ley 40/2015: «1. Se entiende por actuación administrativa automatizada, cualquier acto o actuación realizada íntegramente a través de medios electrónicos por una Administración Pública en el marco de un procedimiento administrativo y en la que no haya intervenido de forma directa un empleado público.»","Art. 1.2 RD 1112/2018: «2. A los efectos de este real decreto se entiende por accesibilidad el conjunto de principios y técnicas que se deben respetar al diseñar, construir, mantener y actualizar los sitios web y las aplicaciones para dispositivos móviles para garantizar la igualdad y la no discriminación en el acceso de las personas usuarias, en particular de las personas con discapacidad y de las personas mayores.»","Art. 10 RD 208/1996: «Mediante convenio de colaboración, suscrito por distintas Administraciones públicas, podrá acordarse que desde las oficinas de información y atención de cualesquiera de ellas pueda ofrecerse a los ciudadanos la información administrativa de las otras, articulándose los mecanismos de comunicación necesarios para el intercambio de la información, así como la creación de oficinas integradas de información con participación de varias Administraciones públicas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, 'Otras normas citadas: RD 203/2021 (https://www.boe.es/buscar/act.php?id=BOE-A-2021-5032), Ley 40/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566), RD 1112/2018 (https://www.boe.es/buscar/act.php?id=BOE-A-2018-12699), RD 208/1996 (https://www.boe.es/buscar/act.php?id=BOE-A-1996-4997)'
  from public.topics t where t.slug = 'age-aux-b2-04-administracion-electronica'
