select t.id, 'es', '[{"n":"1","title":"El escritorio de Windows 11 y la barra de tareas"},{"n":"2","title":"El menú Inicio"},{"n":"2.1","title":"Anclar, reorganizar y crear carpetas"},{"n":"2.2","title":"Alineación y configuración del menú Inicio"},{"n":"3","title":"Ventanas: abrir, cambiar, cerrar y acoplar"},{"n":"3.1","title":"Alt + Tab y la Vista de tareas"},{"n":"3.2","title":"Acoplar ventanas y grupos de acoplamiento"},{"n":"4","title":"Escritorios virtuales"},{"n":"5","title":"Menús contextuales y cuadros de diálogo"},{"n":"6","title":"Métodos abreviados con la tecla Windows"},{"n":"7","title":"Copilot en Windows"}]'::jsonb, '["Tecla Windows Soporte Microsoft (Windows: métodos abreviados): «Tecla Windows | Abrir o cerrar el menú Inicio.»","Windows + D Soporte Microsoft (Windows: métodos abreviados): «Tecla Windows + D | Mostrar y ocultar el escritorio.»","Menú Inicio Soporte Microsoft (menú Inicio): «Para crear una carpeta, arrastre un elemento anclado sobre otro para crear una carpeta.»","Menú Inicio Soporte Microsoft (menú Inicio): «Normalmente, el menú Inicio está centrado, pero puede cambiar la alineación al lado de la barra de tareas.»","Vista de tareas Soporte Microsoft (multitarea en Windows): «La Vista de tareas proporciona información general sobre todas las ventanas abiertas y varios escritorios.»","Alt + Tab Soporte Microsoft (multitarea en Windows): «Una vez que suelte la tecla Alt, la aplicación seleccionada pasará al primer plano.»","Alt + F4 Soporte Microsoft (Windows: métodos abreviados): «Alt+F4 | Cerrar la ventana activa. Si no hay ventanas abiertas, solicite el cierre.»","Acoplar Soporte Microsoft (acoplar ventanas): «El control flotante Acoplar aparece al mantener el puntero sobre el botón Maximizar en una ventana.»","Acoplar Soporte Microsoft (acoplar ventanas): «Los grupos de acoplamiento son colecciones de ventanas que se han acoplado»","Escritorios Soporte Microsoft (Windows: métodos abreviados): «Tecla Windows + Ctrl + D | Crear otro escritorio.»","Escritorios Soporte Microsoft (multitarea en Windows): «Las aplicaciones abiertas en el escritorio cerrado se moverán al siguiente escritorio disponible.»","Menú de la ventana Soporte Microsoft (Windows: métodos abreviados): «Alt+Barra espaciadora | Abrir el menú contextual de la ventana activa.»","Cuadros de diálogo Soporte Microsoft (Windows: métodos abreviados): «Alt+letra subrayada | Ejecutar el comando (o seleccionar la opción) que se usa con la letra.»","Copilot Soporte Microsoft (Copilot en Windows): «Puede encontrar la aplicación Copilot anclada a la barra de tareas o en el menú Inicio.»","Copilot Soporte Microsoft (Windows: métodos abreviados): «Tecla Windows + C | Abre Microsoft Copilot o Microsoft 365 Copilot.»","Copilot Soporte Microsoft (Copilot en Windows): «Copilot Vision puede ver las ventanas del explorador o las aplicaciones que tiene abiertas en la pantalla»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://support.microsoft.com/es-es/accessibility/windows/keyboard-shortcuts-in-windows'), 'https://support.microsoft.com/es-es/accessibility/windows/keyboard-shortcuts-in-windows', null, null, null, 'Otras normas citadas: Soporte Microsoft (menú Inicio) (https://support.microsoft.com/es-es/windows/experience/personalization/customize-the-windows-start-menu), Soporte Microsoft (multitarea en Windows) (https://support.microsoft.com/es-es/windows/experience/how-to-multitask-in-windows), Soporte Microsoft (acoplar ventanas) (https://support.microsoft.com/es-es/windows/experience/snap-your-windows), Soporte Microsoft (Copilot en Windows) (https://support.microsoft.com/es-es/windows/le-damos-la-bienvenida-a-copilot-en-windows-675708af-8c16-4675-afeb-85a5a476ccb0)'
