select t.id, 'es', '[{"n":"1","title":"El Explorador de archivos: funciones y apertura"},{"n":"2","title":"Inicio / Acceso rápido y Este equipo"},{"n":"3","title":"Carpetas y archivos: crear, renombrar, copiar, mover y eliminar"},{"n":"3.1","title":"Menú contextual simplificado"},{"n":"3.2","title":"Opciones de vista y paneles"},{"n":"4","title":"Búsqueda de archivos e indización"},{"n":"5","title":"Archivos comprimidos"},{"n":"6","title":"Accesorios: Herramienta Recortes"},{"n":"7","title":"Herramientas del sistema"}]'::jsonb, '["Explorador Soporte Microsoft (Explorador de archivos): «El Explorador de archivos de Windows te ayuda a encontrar, abrir, organizar y administrar archivos y carpetas»","Explorador Soporte Microsoft (Explorador de archivos): «De forma predeterminada, el Explorador de archivos se abre en Acceso rápido»","Acceso rápido Soporte Microsoft (Explorador de archivos): «Puede configurar cualquier carpeta para que aparezca en Acceso rápido para que sea fácil de encontrar.»","Este equipo Soporte Microsoft (Explorador de archivos): «Estas carpetas predeterminadas ya no se muestran en Este equipo para mantener la vista centrada en las unidades»","Menú contextual Soporte Microsoft (Explorador de archivos): «El Explorador de archivos tiene un menú contextual nuevo y simplificado»","F2 Soporte Microsoft (Windows: métodos abreviados): «F2 | Cambiar el nombre del elemento seleccionado.»","Ctrl + Mayús + N Soporte Microsoft (Windows: métodos abreviados): «Ctrl+Mayús+N | Cree una carpeta nueva.»","Mayús + Supr Soporte Microsoft (Windows: métodos abreviados): «Mayús+Supr | Eliminar permanentemente el elemento seleccionado sin moverlo a la papelera de reciclaje.»","Arrastrar Soporte Microsoft (Windows: métodos abreviados): «Ctrl+mouse arrastrar un archivo | Cuando suelte el archivo, cree una copia en esa ubicación.»","Búsqueda Soporte Microsoft (buscar archivos): «Para realizar una búsqueda lenta pero exhaustiva, busque en Este equipo en lugar de en Inicio.»","Indización Soporte Microsoft (buscar archivos): «Mejore la velocidad de búsqueda y la eficiencia indexando los archivos y sus propiedades»","Comprimir Soporte Microsoft (archivos comprimidos): «Los archivos comprimidos reducen el tamaño del archivo y agrupan varios archivos para facilitar el uso compartido.»","Recortes Soporte Microsoft (Recortes): «Después de capturar un recorte, se guarda automáticamente en la carpeta Capturas de pantalla.»","Administrador de tareas Soporte Microsoft (herramientas del sistema): «El Administrador de tareas es una aplicación que sirve como monitor del sistema y administrador de inicio para Windows»","Información del sistema Soporte Microsoft (herramientas del sistema): «Información del sistema es una utilidad del sistema que proporciona una vista completa del hardware»","Editor del Registro Soporte Microsoft (herramientas del sistema): «El Registro es una base de datos que almacena la configuración de bajo nivel para Windows»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://support.microsoft.com/es-es/windows/experience/fileexplorer/file-explorer-in-windows'), 'https://support.microsoft.com/es-es/windows/experience/fileexplorer/file-explorer-in-windows', null, null, null, 'Otras normas citadas: Soporte Microsoft (Windows: métodos abreviados) (https://support.microsoft.com/es-es/accessibility/windows/keyboard-shortcuts-in-windows), Soporte Microsoft (buscar archivos) (https://support.microsoft.com/es-es/windows/experience/storage-filemanagement/find-your-files-and-apps-in-windows), Soporte Microsoft (archivos comprimidos) (https://support.microsoft.com/es-es/windows/experience/storage-filemanagement/zip-and-unzip-files), Soporte Microsoft (Recortes) (https://support.microsoft.com/es-es/windows/apps/use-snipping-tool-to-capture-screenshots), Soporte Microsoft (herramientas del sistema) (https://support.microsoft.com/es-es/windows/experience/system-configuration-tools-in-windows)'
