insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Funciones y utilidades de Word 365"},{"n":"1.1","title":"Métodos abreviados de teclado y teclas de función"},{"n":"1.2","title":"Revisión: Editor, sinónimos y control de cambios"},{"n":"2","title":"Creación y estructuración del documento"},{"n":"2.1","title":"Plantillas, estilos y títulos"},{"n":"2.2","title":"Tabla de contenido"},{"n":"2.3","title":"Encabezados, pies de página y saltos"},{"n":"2.4","title":"Combinar correspondencia"},{"n":"3","title":"Gestión, grabación, recuperación e impresión"},{"n":"3.1","title":"Guardar, formatos de archivo y Autoguardado"},{"n":"3.2","title":"Vistas e impresión"},{"n":"4","title":"Personalización del entorno: cinta de opciones"}]'::jsonb, '["Teclas de función Soporte Microsoft (Word, atajos): «Solo F12: muestra el cuadro de diálogo Guardar como.»","Teclas de función Soporte Microsoft (Word, atajos): «Solo F4: repite el último comando o acción, si es posible.»","Teclas de función Soporte Microsoft (Word, atajos): «Mayús+F7: muestra el panel de tareas del diccionario de sinónimos.»","Métodos abreviados Soporte Microsoft (Word, atajos): «Insertar un salto de página. | Ctrl+Entrar»","Control de cambios Soporte Microsoft (Word, control de cambios): «Las eliminaciones se marcan con un tachado y las adiciones se marcan con un subrayado.»","Control de cambios Soporte Microsoft (Word, control de cambios): «Debe utilizar los comandos Aceptar y Rechazar en el grupo Cambios para quitar la marcación del documento.»","Plantillas Soporte Microsoft (Word, tareas básicas): «A menudo es más fácil crear un documento nuevo con una plantilla en lugar de empezar con una página en blanco.»","Tabla de contenido Soporte Microsoft (Word, tabla de contenido): «Una tabla de contenido en Word se basa en los títulos del documento.»","Tabla de contenido Soporte Microsoft (Word, tabla de contenido): «Las entradas que faltan a menudo se producen porque los títulos no tienen formato de títulos.»","Encabezados y pies Soporte Microsoft (Word, encabezados y pies): «Haga clic en Cerrar encabezado y pie de página o presione Esc para salir.»","Combinar correspondencia Soporte Microsoft (Word, combinar correspondencia): «Todos los datos que se combinarán están presentes en la primera hoja de la hoja de cálculo.»","Guardar Soporte Microsoft (Word, tareas básicas): «Word guarda los archivos automáticamente con el formato de archivo .docx.»","Autoguardado Soporte Microsoft (Office, guardar y recuperar): «Autoguardado guarda automáticamente el archivo cuando un archivo está almacenado en OneDrive o SharePoint en Microsoft 365.»","Vistas Soporte Microsoft (Word, tareas básicas): «Abra el documento en Modo Lectura para ocultar la mayor parte de los botones y las herramientas.»","Personalizar la cinta Soporte Microsoft (Word, personalizar la cinta): «No puede cambiar el color de la cinta de opciones o sus iconos»","Personalizar la cinta Soporte Microsoft (Word, personalizar la cinta): «Solo se pueden restablecer las pestañas predeterminadas a su configuración predeterminada.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://support.microsoft.com/es-es/accessibility/word/keyboard-shortcuts-in-word'), 'https://support.microsoft.com/es-es/accessibility/word/keyboard-shortcuts-in-word', null, null, null, 'Otras normas citadas: Soporte Microsoft (Word, control de cambios) (https://support.microsoft.com/es-es/word/training/track-changes-in-word), Soporte Microsoft (Word, tareas básicas) (https://support.microsoft.com/es-es/office/tareas-b%C3%A1sicas-en-word-87b3243c-b0bf-4a29-82aa-09a681999fdc), Soporte Microsoft (Word, tabla de contenido) (https://support.microsoft.com/es-es/office/insertar-una-tabla-de-contenido-882e8564-0edb-435e-84b5-1d8552ccf0c0), Soporte Microsoft (Word, encabezados y pies) (https://support.microsoft.com/es-es/office/insertar-un-encabezado-o-pie-de-p%C3%A1gina-b87ee4df-abc1-41f8-995b-b39f6d99c7ed), Soporte Microsoft (Word, combinar correspondencia) (https://support.microsoft.com/es-es/office/combinar-correspondencia-con-una-hoja-de-c%C3%A1lculo-de-excel-858c7d7f-5cc0-4ba1-9a7b-0a948fa3d7d3), Soporte Microsoft (Office, guardar y recuperar) (https://support.microsoft.com/es-es/office/guardar-realizar-copias-de-seguridad-y-recuperar-un-archivo-en-microsoft-office-a7f0a209-ad22-4212-bb53-6cd8e801a6fb), Soporte Microsoft (Word, personalizar la cinta) (https://support.microsoft.com/es-es/office/personalizar-la-cinta-de-opciones-en-word-c4b6051a-7a70-43c8-a527-932917dec682)'
