insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El entorno de Outlook: correo, calendario, contactos y tareas"},{"n":"1.1","title":"Barra de herramientas de acceso rápido y cinta de opciones"},{"n":"2","title":"Crear y enviar mensajes"},{"n":"2.1","title":"Destinatarios: Para, CC y CCO"},{"n":"2.2","title":"Datos adjuntos"},{"n":"3","title":"Responder, responder a todos y reenviar"},{"n":"4","title":"Reglas de correo electrónico"},{"n":"4.1","title":"Crear una regla desde un mensaje o desde una plantilla"},{"n":"4.2","title":"Respuestas de Fuera de la oficina mediante reglas"},{"n":"5","title":"La libreta de direcciones"}]'::jsonb, '["Correo Soporte Microsoft (Outlook: tareas básicas): «Para crear un mensaje de correo electrónico, presione Ctrl+Mayús+M.»","Calendario Soporte Microsoft (Outlook: tareas básicas): «En Outlook, una reunión incluye a otras personas y puede incluir recursos como salas de conferencias.»","Tareas Soporte Microsoft (Outlook: tareas básicas): «Para crear una tarea, presione Ctrl+Mayús+K.»","Barra de acceso rápido Soporte Microsoft (Outlook: tareas básicas): «Puede controlar qué botones (o iconos) aparecen en la barra de acceso rápido»","CCO Soporte Microsoft (Outlook: CCO): «Otras personas que reciben el mensaje no ven la dirección en la línea CCO.»","CCO Soporte Microsoft (Outlook: CCO): «recuerde que los nombres del cuadro CCO contarán para el límite total.»","Responder Soporte Microsoft (Outlook: responder y reenviar): «Responder solo envía el nuevo mensaje al remitente original. Los datos adjuntos no están incluidos.»","Responder a todos Soporte Microsoft (Outlook: responder y reenviar): «Responder a todos envía el nuevo mensaje al remitente original y a todos los demás destinatarios en las líneas Para y Cc.»","Reenviar Soporte Microsoft (Outlook: responder y reenviar): «Reenviar le permite escribir un conjunto completamente nuevo de destinatarios.»","Reenviar Soporte Microsoft (Outlook: responder y reenviar): «Los datos adjuntos incluidos en el mensaje original se incluyen automáticamente al reenviar un mensaje.»","Reglas Soporte Microsoft (reglas de Outlook): «Las reglas le permiten mover, marcar y responder a mensajes de correo electrónico automáticamente.»","Reglas Soporte Microsoft (reglas de Outlook): «Haga clic con el botón derecho en un mensaje existente y seleccione Reglas > Crear regla.»","Reglas Soporte Microsoft (reglas de Outlook): «Elija Archivo > Administrar reglas y alertas > Nueva regla.»","Fuera de la oficina Soporte Microsoft (Outlook: Fuera de la oficina): «En la lista desplegable Guardar como tipo, seleccione Plantilla de Outlook (*.oft).»","Libreta de direcciones Soporte Microsoft (Outlook: libreta de direcciones): «Si usa Outlook con una cuenta de Exchange Server, la lista de libretas de direcciones incluirá la lista global de direcciones (LGD).»","Libreta de direcciones Soporte Microsoft (Outlook clásico: crear libreta de direcciones): «La Libreta de direcciones está en el lateral de la pestaña Inicio.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://support.microsoft.com/es-es/outlook/basic-tasks-in-outlook'), 'https://support.microsoft.com/es-es/outlook/basic-tasks-in-outlook', null, null, null, 'Otras normas citadas: Soporte Microsoft (Outlook: CCO) (https://support.microsoft.com/es-es/outlook/mail/show-hide-and-view-the-bcc-blind-carbon-copy-field-in-outlook-for-windows), Soporte Microsoft (Outlook: responder y reenviar) (https://support.microsoft.com/es-es/office/responder-o-reenviar-un-mensaje-de-correo-electr%C3%B3nico-a843f8d3-01b0-48da-96f5-a71f70d0d7c8), Soporte Microsoft (reglas de Outlook) (https://support.microsoft.com/es-es/office/configurar-reglas-en-outlook-75ab719a-2ce8-49a7-a214-6d62b67cbd41), Soporte Microsoft (Outlook: Fuera de la oficina) (https://support.microsoft.com/es-es/outlook/use-rules-to-create-an-out-of-office-message-in-outlook?ad=es&omkt=es-es&rs=es-es&ui=es-es), Soporte Microsoft (Outlook: libreta de direcciones) (https://support.microsoft.com/es-es/outlook/open-and-use-the-address-book-in-outlook), Soporte Microsoft (Outlook clásico: crear libreta de direcciones) (https://support.microsoft.com/es-ES/Outlook/create-an-address-book-in-classic-outlook)'
