select t.id, 'es', '[{"n":"1","title":"Internet: protocolos y servicios"},{"n":"1.1","title":"DNS: resolución de nombres"},{"n":"1.2","title":"HTTP: solicitudes, respuestas y direcciones URL"},{"n":"2","title":"Navegadores: Microsoft Edge"},{"n":"2.1","title":"Pestañas, ventanas, historial, descargas y favoritos"},{"n":"2.2","title":"Exploración InPrivate"},{"n":"3","title":"Navegación segura"},{"n":"3.1","title":"SmartScreen de Microsoft Defender y prevención de seguimiento"},{"n":"3.2","title":"Seguridad de la conexión, descargas y actualizaciones"}]'::jsonb, '["DNS Microsoft Learn (DNS): «En las redes de Windows, DNS es el servicio de resolución de nombres predeterminado.»","DNS Microsoft Learn (DNS): «DNS forma parte de la capa de aplicación del modelo de referencia TCP/IP, como se muestra en la ilustración siguiente.»","HTTP Microsoft Learn (HTTP): «Un explorador solo realiza solicitudes y el servidor atiende las solicitudes del cliente con respuestas.»","URL Microsoft Learn (HTTP): «Las cadenas de consulta siempre se separan del resto de la dirección URL mediante un signo de interrogación.»","Edge Soporte Microsoft (Edge: métodos abreviados): «Ctrl+T | Abrir una pestaña nueva y cambiar a ella»","Edge Soporte Microsoft (Edge: métodos abreviados): «Ctrl+Mayús+T | Volver a abrir la última pestaña cerrada y cambiar a ella»","Edge Soporte Microsoft (Edge: métodos abreviados): «Ctrl+H | Abrir historial»","Edge Soporte Microsoft (Edge: métodos abreviados): «Ctrl+J | Abrir Descargas»","Edge Soporte Microsoft (Edge: métodos abreviados): «Ctrl+Mayús+ Suprimir | Abrir las opciones de borrar los datos de exploración»","InPrivate Soporte Microsoft (Edge: InPrivate): «La ventana de InPrivate en Microsoft Edge le permite navegar por la Web sin guardar el historial de exploración»","InPrivate Soporte Microsoft (Edge: InPrivate): «permitir guardar descargas y favoritos.»","SmartScreen Soporte Microsoft (Edge: seguridad): «SmartScreen de Microsoft Defender le ayuda a protegerse de sitios de suplantación de identidad (phishing)»","Prevención de seguimiento Soporte Microsoft (Edge: seguridad): «Puedes elegir entre tres niveles de prevención de seguimiento: Básico, Equilibrado y Estricto.»","Conexión Soporte Microsoft (Edge: seguridad): «Mientras navega por la Web, verá un icono en la barra de direcciones que indica la seguridad de la conexión»","Descargas Soporte Microsoft (Edge: seguridad): «descarga solo archivos de sitios web y fuentes de confianza.»","Actualizaciones Soporte Microsoft (Edge: seguridad): «Puede habilitar las actualizaciones automáticas para recibir automáticamente las correcciones de seguridad más recientes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://support.microsoft.com/es-es/microsoft-edge/m%C3%A9todos-abreviados-de-teclado-en-microsoft-edge-50d3edab-30d9-c7e4-21ce-37fe2713cfad'), 'https://support.microsoft.com/es-es/microsoft-edge/m%C3%A9todos-abreviados-de-teclado-en-microsoft-edge-50d3edab-30d9-c7e4-21ce-37fe2713cfad', null, null, null, 'Otras normas citadas: Microsoft Learn (DNS) (https://learn.microsoft.com/es-es/windows-server/networking/dns/dns-overview), Microsoft Learn (HTTP) (https://learn.microsoft.com/es-es/xandr/industry-reference/intro-to-http), Soporte Microsoft (Edge: InPrivate) (https://support.microsoft.com/es-es/edge/browse-inprivate-in-microsoft-edge), Soporte Microsoft (Edge: seguridad) (https://support.microsoft.com/es-es/edge/securely-browse-the-web-in-microsoft-edge)'
